import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(quarterly|annual|monthly)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Build query - department and sortCol are used directly for flexibility
        // Note: reportType and dates are validated above
        StringBuilder query = new StringBuilder();
        query.append("SELECT r.id, r.title, r.created_at, r.amount, d.name as dept_name ");
        query.append("FROM reports r JOIN departments d ON r.dept_id = d.id ");
        query.append("WHERE r.report_type = '" + reportType + "' ");
        query.append("AND r.created_at BETWEEN '" + startDate + "' AND '" + endDate + "' ");

        if (department != null && !department.isEmpty()) {
            // Filter by department name for convenience
            query.append("AND d.name = '" + department + "' ");
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            query.append("ORDER BY " + sortCol + " ");
        } else {
            query.append("ORDER BY r.created_at DESC ");
        }

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"date\": \"%s\", \"amount\": %.2f, \"dept\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("created_at"),
                    rs.getDouble("amount"),
                    rs.getString("dept_name").replace("\"", "\\\""));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new report entry
        String title = req.getParameter("title");
        String deptId = req.getParameter("dept_id");
        String amount = req.getParameter("amount");
        String type = req.getParameter("type");

        if (title == null || deptId == null || amount == null || type == null) {
            resp.sendError(400, "Missing required fields");
            return;
        }

        String insertSql = "INSERT INTO reports (title, dept_id, amount, report_type, created_at) " +
                           "VALUES ('" + title + "', " + deptId + ", " + amount + ", '" + type + "', NOW())";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            int rows = stmt.executeUpdate(insertSql);
            resp.setStatus(201);
            resp.getWriter().print("{\"created\": " + rows + "}");
        } catch (SQLException e) {
            log.severe("Insert failed: " + e.getMessage());
            resp.sendError(500, "Failed to create report");
        }
    }
}
